const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '动力臂' },
      { kind: 'text', payload: '阻力臂' },
      { kind: 'text', payload: '支点' },
      { kind: 'text', payload: '动力臂∶阻力臂 = 2∶1' }
    ];
  },
  render: function (input, metrics) {
    var line = function (x1, y1, x2, y2) { return [['M', x1, y1], ['L', x2, y2]]; };
    var poly = function (pts) {
      var c = [['M', pts[0][0], pts[0][1]]];
      for (var i = 1; i < pts.length; i = i + 1) { c.push(['L', pts[i][0], pts[i][1]]); }
      return c;
    };
    var closed = function (pts) { return poly(pts).concat([['Z']]); };

    var B = { x: 140, y: 220 };
    var C = { x: 600, y: 322 };
    var F = { x: C.x + (B.x - C.x) / 3, y: C.y + (B.y - C.y) / 3 };

    var dx = C.x - B.x;
    var dy = C.y - B.y;
    var len = Math.sqrt(dx * dx + dy * dy);
    var ux = dx / len;
    var uy = dy / len;
    var nx = uy;
    var ny = -ux;
    var off = function (p, t) { return { x: p.x + nx * t, y: p.y + ny * t }; };

    var GROUND = 340;
    var barEnd = { x: C.x + ux * 44, y: C.y + uy * 44 };
    var apex = off(F, -6.5);

    var e = 42;
    var eB = off(B, e);
    var eF = off(F, e);
    var eC = off(C, e);
    var b7 = off(B, 7);
    var b52 = off(B, 52);
    var f7 = off(F, 7);
    var f52 = off(F, 52);
    var c7 = off(C, 7);
    var c52 = off(C, 52);

    var labPower = off({ x: (eB.x + eF.x) / 2, y: (eB.y + eF.y) / 2 }, 26);
    var labResist = off({ x: (eF.x + eC.x) / 2, y: (eF.y + eC.y) / 2 }, 26);

    var hatch = [];
    for (var i = 0; i < 16; i = i + 1) {
      var hx = 46 + i * 42;
      hatch = hatch.concat(line(hx, GROUND, hx - 12, GROUND + 12));
    }

    var paths = [
      { id: 'ground', commands: line(30, GROUND, 690, GROUND) },
      { id: 'hatch', commands: hatch },
      { id: 'fulcrum', commands: closed([[apex.x, apex.y], [apex.x - 38, GROUND], [apex.x + 38, GROUND]]) },
      { id: 'bar', commands: line(B.x, B.y, barEnd.x, barEnd.y) },
      { id: 'rock', commands: closed([[600, GROUND], [616, 278], [644, 250], [672, 286], [678, GROUND]]) },
      { id: 'pivotDot', commands: visualSdk.circle(F.x, F.y, 4) },
      { id: 'dim', commands: line(eB.x, eB.y, eF.x, eF.y).concat(line(eF.x, eF.y, eC.x, eC.y)) },
      { id: 'ext', commands: line(b7.x, b7.y, b52.x, b52.y).concat(line(f7.x, f7.y, f52.x, f52.y)).concat(line(c7.x, c7.y, c52.x, c52.y)) },
      { id: 'leader', commands: line(392, 316, 424, 318) }
    ];

    var root = { type: 'group', children: [
      { type: 'path', pathId: 'hatch', stroke: '#94a3b8', strokeWidth: 1.4, fill: 'none' },
      { type: 'path', pathId: 'ground', stroke: '#334155', strokeWidth: 2.6, fill: 'none' },
      { type: 'path', pathId: 'fulcrum', fill: '#cbd5e1', stroke: '#475569', strokeWidth: 2 },
      { type: 'path', pathId: 'bar', stroke: '#9c6b3f', strokeWidth: 13, strokeLinecap: 'round', fill: 'none' },
      { type: 'path', pathId: 'rock', fill: '#b3bcc6', stroke: '#4b5563', strokeWidth: 2 },
      { type: 'path', pathId: 'pivotDot', fill: '#c0392b', stroke: 'none' },
      { type: 'path', pathId: 'ext', stroke: '#c0392b', strokeWidth: 1.2, fill: 'none' },
      { type: 'path', pathId: 'dim', stroke: '#c0392b', strokeWidth: 1.8, strokeLinecap: 'round', fill: 'none' },
      { type: 'path', pathId: 'leader', stroke: '#1f2d3d', strokeWidth: 1.2, fill: 'none' },
      { type: 'label', text: '动力臂', x: labPower.x, y: labPower.y, fontSize: 20, fill: '#c0392b', align: 'center', baseline: 'middle' },
      { type: 'label', text: '阻力臂', x: labResist.x, y: labResist.y, fontSize: 20, fill: '#c0392b', align: 'center', baseline: 'middle' },
      { type: 'label', text: '支点', x: 368, y: 316, fontSize: 20, fill: '#1f2d3d', align: 'center', baseline: 'middle' },
      { type: 'label', text: '动力臂∶阻力臂 = 2∶1', x: 330, y: 58, fontSize: 19, fill: '#1f2d3d', align: 'center', baseline: 'middle' }
    ] };

    return {
      schemaVersion: 1,
      sceneId: 'crowbar-lever',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: input.viewport.widthDu, height: input.viewport.heightDu },
      paths: paths,
      root: root
    };
  }
};
